[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Dish</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     DISH PRINT FORMAT
     SECTION 1: COMPANY HEADER + DOCUMENT DETAILS
     ========================================================= -->

<table style="
    width: 100%;
    border-collapse: collapse;
    border: 1.5px solid #1c3f60;
    font-family: Arial, Helvetica, sans-serif;
">

    <tr>

        <!-- COMPANY -->
        <td style="
            width: 60%;
            padding: 8px 10px;
            vertical-align: middle;
            border-right: 1px solid #1c3f60;
        ">

            <div style="
                font-size: 15px;
                font-weight: bold;
                color: #11466a;
                letter-spacing: 0.3px;
            ">
                ENERTECH UPS PVT. LTD.
            </div>

            <div style="
                margin-top: 2px;
                font-size: 8px;
                color: #666;
                font-style: italic;
            ">
                Answering All Power Needs
            </div>

        </td>


        <!-- DOCUMENT DETAILS -->
        <td style="
            width: 40%;
            padding: 8px 10px;
            vertical-align: middle;
            text-align: center;
            font-size: 8px;
            line-height: 1.5;
        ">

            Document No – EUPL/MKTG/FR/01
            <br>

            REV. No. – 01
            <br>

            Updated-1.10.2017

        </td>

    </tr>

</table>


<!-- =========================================================
     DATE + DISH NUMBER
     ========================================================= -->

<table style="
    width: 100%;
    border-collapse: collapse;
    font-family: Arial, Helvetica, sans-serif;
">

    <tr>

        <td style="
            width: 50%;
            background: #c8631a;
            color: #fff;
            font-size: 13px;
            font-weight: bold;
            padding: 6px 10px;
            border: 1px solid #c8631a;
        ">
            DATE.:
            {{ frappe.utils.formatdate(doc.date, "dd/MM/yyyy") if doc.date else "" }}
        </td>

        <td style="
            width: 50%;
            background: #c8631a;
            color: #fff;
            font-size: 13px;
            font-weight: bold;
            padding: 6px 10px;
            border: 1px solid #c8631a;
        ">
            DISH NO. :
            {{ doc.dish_no or "" }}
        </td>

    </tr>

</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     SECTION 2: CUSTOMER / ORDER / BUYER / DISPATCH DETAILS
     ========================================================= -->

<table style="
    width: 100%;
    border-collapse: collapse;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 9px;
    margin-top: 6px;
">

    <!-- HEADER ROW -->
    <tr>

        <td style="
            width: 33.33%;
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Customer Details
        </td>

        <td style="
            width: 33.33%;
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Purchase Order No.
        </td>

        <td style="
            width: 33.33%;
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Mode/Terms of Payment
        </td>

    </tr>


    <!-- CUSTOMER / PO / PAYMENT -->
    <tr>

        <!-- CUSTOMER -->
        <td rowspan="4" style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">

            <div style="font-weight: bold;">
                {{ doc.customer_name or doc.customer or "" }}
            </div>

            <div style="
                margin-top: 3px;
                color: #444;
                line-height: 1.3;
            ">
                {{ doc.customer_address or "" }}
            </div>

            {% if doc.contact_no %}
            <div style="margin-top: 3px;">
                Contact No: {{ doc.contact_no }}
            </div>
            {% endif %}

            {% if doc.gst_no %}
            <div style="
                margin-top: 3px;
                font-weight: bold;
            ">
                GST NO : {{ doc.gst_no }}
            </div>
            {% endif %}

        </td>


        <!-- PURCHASE ORDER -->
        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">
            {{ doc.purchase_order_no or "" }}
        </td>


        <!-- PAYMENT TERMS -->
        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">
            {{ doc.modeterms_of_payment or "" }}
        </td>

    </tr>


    <!-- ORDER DATE / BANK GUARANTEE -->

    <tr>

        <td style="
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Order Date.
        </td>

        <td style="
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Bank Guarranty Details If Any
        </td>

    </tr>


    <tr>

        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">
            {{ frappe.utils.formatdate(doc.order_date, "dd-MMM-yy")
               if doc.order_date else "" }}
        </td>

        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">
            {{ doc.bank_guarantee_details or "" }}
        </td>

    </tr>


    <!-- EXPECTED DELIVERY / C FORM -->

    <tr>

        <td style="
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Expected Delivery
        </td>

        <td style="
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            C Form Status Y/N:
        </td>

    </tr>


    <tr>

        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
        ">
            {{ frappe.utils.formatdate(doc.expected_delivery, "dd/MM/yyyy")
               if doc.expected_delivery else "" }}
        </td>

        <td style="
            padding: 6px 8px;
            border: 1px solid #999;
        ">
            {{ doc.c_form_status or "" }}
        </td>

    </tr>


    <!-- BUYER + MODE OF DISPATCH -->

    <tr>

        <td style="
            width: 33.33%;
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Buyer Details
        </td>

        <td colspan="2" style="
            padding: 5px 8px;
            border: 1px solid #999;
            background: #eef3f7;
            color: #11466a;
            font-weight: bold;
        ">
            Mode of Dispatch
        </td>

    </tr>


    <tr>

        <!-- BUYER -->
        <td rowspan="2" style="
            padding: 6px 8px;
            border: 1px solid #999;
            vertical-align: top;
        ">

            <div style="font-weight: bold;">
                {{ doc.buyers_name or doc.buyer or "" }}
            </div>

            <div style="
                margin-top: 3px;
                color: #444;
                line-height: 1.3;
            ">
                {{ doc.buyer_address or "" }}
            </div>

            {% if doc.buyer_contact_no %}
            <div style="margin-top: 3px;">
                Contact No: {{ doc.buyer_contact_no }}
            </div>
            {% endif %}

            {% if doc.buyers_email %}
            <div style="margin-top: 3px;">
                Email: {{ doc.buyers_email }}
            </div>
            {% endif %}

            {% if doc.bueyer_gst_no %}
            <div style="
                margin-top: 3px;
                font-weight: bold;
            ">
                GST NO : {{ doc.bueyer_gst_no }}
            </div>
            {% endif %}

        </td>


        <!-- MODE OF DISPATCH -->
        <td colspan="2" style="
            padding: 6px 8px;
            border: 1px solid #999;
            font-weight: bold;
        ">
            {{ doc.mode_of_dispatch or "" }}
        </td>

    </tr>

</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
