</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     SECTION 4: ITEM / DESCRIPTION TABLE
     ========================================================= -->

<table style="
    width: 100%;
    border-collapse: collapse;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 8.5px;
    margin-top: 6px;
">

    <thead>

        <tr style="
            background: #11466a;
            color: #ffffff;
        ">

            <th style="
                width: 6%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: center;
            ">
                No.
            </th>

            <th style="
                width: 30%;
                padding: 5px 4px;
                border: 1px solid #1c3f60;
                text-align: left;
            ">
                Item / Description
            </th>

            <th style="
                width: 10%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: center;
            ">
                Warranty
            </th>

            <th style="
                width: 9%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: center;
            ">
                HSN Code
            </th>

            <th style="
                width: 9%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: center;
            ">
                Quantity
            </th>

            <th style="
                width: 10%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: right;
            ">
                Rate
            </th>

            <th style="
                width: 12%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: center;
            ">
                GST
            </th>

            <th style="
                width: 14%;
                padding: 5px 3px;
                border: 1px solid #1c3f60;
                text-align: right;
            ">
                Amount
            </th>

        </tr>

    </thead>


    <tbody>

        {% for row in doc.items %}

        <tr style="
            page-break-inside: avoid;
            break-inside: avoid;
        ">

            <!-- NO. -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: center;
                vertical-align: top;
            ">
                {{ loop.index }}
            </td>


            <!-- ITEM / DESCRIPTION -->

            <td style="
                border: 1px solid #999;
                padding: 5px 4px;
                vertical-align: top;
                word-break: break-word;
            ">

                <div style="font-weight: bold;">
                    {{ row.item_code }}
                </div>

                <div style="
                    font-weight: bold;
                    margin-top: 2px;
                ">
                    {{ row.item_name }}
                </div>

                {% if row.description %}

                <div style="
                    margin-top: 3px;
                    font-size: 8px;
                    line-height: 1.3;
                    color: #444;
                    white-space: pre-wrap;
                ">
                    {{ row.description }}
                </div>

                {% endif %}

            </td>


            <!-- WARRANTY -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: center;
                vertical-align: top;
            ">
                {{ row.warranty or "" }}
            </td>


            <!-- HSN -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: center;
                vertical-align: top;
            ">
                {{ row.hsn_code or "" }}
            </td>


            <!-- QUANTITY -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: center;
                vertical-align: top;
            ">
                {{ row.qty or "" }}
                {% if row.uom %}
                    {{ row.uom }}
                {% endif %}
            </td>


            <!-- RATE -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: right;
                vertical-align: top;
                white-space: nowrap;
            ">
                {{ frappe.utils.fmt_money(row.rate or 0, currency="INR") }}
            </td>


            <!-- GST -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: center;
                vertical-align: top;
            ">

                {% if row.igst_rate %}

                    <div>
                        IGST
                        {{ frappe.utils.flt(row.igst_rate)|round(0)|int }}%
                    </div>

                    <div style="margin-top: 3px;">
                        {{ frappe.utils.fmt_money(row.igst_amount or 0, currency="INR") }}
                    </div>

                {% else %}

                    <div>
                        CGST
                        {{ frappe.utils.flt(row.cgst_rate)|round(0)|int }}%
                    </div>

                    <div>
                        SGST
                        {{ frappe.utils.flt(row.sgst_rate)|round(0)|int }}%
                    </div>

                    <div style="margin-top: 3px;">
                        {{ frappe.utils.fmt_money(
                            (row.cgst_amount or 0) + (row.sgst_amount or 0),
                            currency="INR"
                        ) }}
                    </div>

                {% endif %}

            </td>


            <!-- AMOUNT -->

            <td style="
                border: 1px solid #999;
                padding: 5px 3px;
                text-align: right;
                vertical-align: top;
                font-weight: bold;
                white-space: nowrap;
            ">
                {{ frappe.utils.fmt_money(row.amount or 0, currency="INR") }}
            </td>

        </tr>

        {% endfor %}

    </tbody>

</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     SECTION 5: AMOUNT IN WORDS + TOTALS
     ========================================================= -->

<div style="
    width:100%;
    margin-top:6px;
    font-family:Arial, Helvetica, sans-serif;
">

    <table style="
        width:100%;
        border-collapse:collapse;
    ">

        <tr>

            <!-- AMOUNT IN WORDS -->

            <td style="
                width:55%;
                vertical-align:top;
                padding-right:10px;
            ">

                <table style="
                    width:100%;
                    border-collapse:collapse;
                ">

                    <tr>
                        <td style="
                            background:#11466a;
                            color:#ffffff;
                            border:1px solid #1c3f60;
                            padding:5px 7px;
                            font-size:8px;
                            font-weight:bold;
                        ">
                            TOTAL AMOUNT (IN WORDS)
                        </td>
                    </tr>

                    <tr>
                        <td style="
                            border:1px solid #999;
                            border-top:none;
                            padding:7px 8px;
                            font-size:9px;
                            font-weight:bold;
                        ">
                            {{ frappe.utils.money_in_words(doc.total or 0, "INR") }}
                        </td>
                    </tr>

                </table>

            </td>


            <!-- TOTALS -->

            <td style="
                width:45%;
                vertical-align:top;
            ">

                <table style="
                    width:100%;
                    border-collapse:collapse;
                    font-size:9px;
                ">

                    <tr>

                        <td style="
                            width:70%;
                            border:1px solid #999;
                            padding:5px 8px;
                            font-weight:bold;
                            text-align:right;
                        ">
                            Sub Total
                        </td>

                        <td style="
                            width:30%;
                            border:1px solid #999;
                            padding:5px 8px;
                            text-align:right;
                        ">
                            {{ frappe.utils.fmt_money(doc.sub_total or 0, currency="INR") }}
                        </td>

                    </tr>


                    <tr>

                        <td style="
                            border:1px solid #999;
                            padding:5px 8px;
                            font-weight:bold;
                            text-align:right;
                        ">
                            GST@{{ frappe.utils.flt(doc.gst_rate)|round(0)|int }}%
                        </td>

                        <td style="
                            border:1px solid #999;
                            padding:5px 8px;
                            text-align:right;
                        ">
                            {{ frappe.utils.fmt_money(doc.gst_amount or 0, currency="INR") }}
                        </td>

                    </tr>


                    <tr>

                        <td style="
                            border:1px solid #999;
                            padding:6px 8px;
                            font-weight:bold;
                            text-align:right;
                            background:#eef6fb;
                        ">
                            Total
                        </td>

                        <td style="
                            border:1px solid #999;
                            padding:6px 8px;
                            font-weight:bold;
                            text-align:right;
                            background:#eef6fb;
                        ">
                            {{ frappe.utils.fmt_money(doc.total or 0, currency="INR") }}
                        </td>

                    </tr>

                </table>

            </td>

        </tr>

    </table>

</div>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
